// Merges all HIL test projects (labels, MQTT data fields, level indicators)
// into a single project: union of screens/topics/fonts, one upload. Each
// source project is either a hand-built export (label-test-project.zip) or
// generated by its own build-project.js (mqtt-field-test/,
// level-indicator-test/ - run `node build-project.js` in those folders
// first if their .zip is missing or stale).
const fs = require("fs");
const path = require("path");
const JSZip = require(path.join(__dirname, "..", "node_modules", "jszip"));

const SOURCE_ZIPS = [
  path.join(__dirname, "label-test-project.zip"),
  path.join(__dirname, "mqtt-field-test", "mqtt-field-test.zip"),
  path.join(__dirname, "level-indicator-test", "level-indicator-test.zip"),
];
const OUT_ZIP = path.join(__dirname, "combined-test-project.zip");

async function loadProject(zipPath) {
  const buf = fs.readFileSync(zipPath);
  const zip = await JSZip.loadAsync(buf);
  const project = JSON.parse(await zip.file("project.json").async("string"));
  return { project, zip };
}

async function main() {
  const loaded = await Promise.all(SOURCE_ZIPS.map(loadProject));

  const combined = {
    ...loaded[0].project,
    name: "Combined Test Project",
    screens: loaded.flatMap((l) => l.project.screens),
    topics: loaded.reduce((topics, l) => {
      for (const t of l.project.topics || []) {
        if (!topics.some((existing) => existing.topic === t.topic)) topics.push(t);
      }
      return topics;
    }, []),
    // fonts are identical across all three source projects (same 4 helvR
    // sizes) - keep the first project's list.
    exportedAt: new Date().toISOString(),
  };

  const outZip = new JSZip();
  outZip.file("project.json", JSON.stringify(combined, null, 2));
  // Copy font files from the first project's zip.
  const fontsZip = loaded[0].zip;
  for (const f of combined.fonts) {
    const entry = fontsZip.file(f.path);
    if (entry) {
      outZip.file(f.path, await entry.async("nodebuffer"));
    }
  }

  const buf = await outZip.generateAsync({ type: "nodebuffer" });
  fs.writeFileSync(OUT_ZIP, buf);
  console.log("Wrote", OUT_ZIP);
  console.log("Screens:", combined.screens.map((s) => s.name));
  console.log("Topics:", combined.topics.map((t) => t.topic));
}

main().catch((e) => { console.error(e); process.exit(1); });
